DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.crea_conferimento_privato_atomico(uuid,uuid,uuid,text,text,text,jsonb,date,numeric,text,text,text,text)'::regprocedure) INTO definition; definition:=replace(definition,E'FROM public.privati_conferimenti\n  WHERE privato_id',E'FROM public.privati_conferimenti_attivi\n  WHERE privato_id'); EXECUTE definition; END; $$;